#!/usr/bin/env python3
# CPU-only, deterministic, read-only symbolic check for K-FW-004.
from fractions import Fraction


def migrate_formula(total, prefix, suffix_bucket):
    if total < 0 or prefix < 0 or prefix > total or suffix_bucket < 0:
        raise ValueError('invalid lengths')
    suffix = total - prefix
    if suffix > suffix_bucket:
        return None
    moved = min(prefix, suffix_bucket - suffix)
    return {
        'prefix_eff': prefix - moved,
        'moved': moved,
        'suffix_eff': suffix + moved,
        'pad': suffix_bucket - (suffix + moved),
    }


def migrate_tokens(total, prefix, suffix_bucket):
    if total < 0 or prefix < 0 or prefix > total or suffix_bucket < 0:
        raise ValueError('invalid lengths')
    pre = list(range(prefix))
    suf = list(range(prefix, total))
    if len(suf) > suffix_bucket:
        return None
    moved = 0
    while len(suf) < suffix_bucket and pre:
        token = pre.pop()
        suf.insert(0, token)
        moved += 1
    if pre + suf != list(range(total)):
        raise AssertionError('token identity/order lost')
    return (len(pre), moved, len(suf), suffix_bucket - len(suf), tuple(pre), tuple(suf))


def bad_no_move(total, prefix, suffix_bucket):
    if total < 0 or prefix < 0 or prefix > total or suffix_bucket < 0:
        raise ValueError('invalid lengths')
    suffix = total - prefix
    if suffix > suffix_bucket:
        return None
    return (prefix, 0, suffix, suffix_bucket - suffix)


def bad_overfill(total, prefix, suffix_bucket):
    if total < 0 or prefix < 0 or prefix > total or suffix_bucket < 0:
        raise ValueError('invalid lengths')
    suffix = total - prefix
    if suffix > suffix_bucket:
        return None
    moved = min(prefix, suffix_bucket - suffix + 1)
    return (suffix + moved) > suffix_bucket


def bad_front_move(total, prefix, suffix_bucket):
    if total < 0 or prefix < 0 or prefix > total or suffix_bucket < 0:
        raise ValueError('invalid lengths')
    pre = list(range(prefix))
    suf = list(range(prefix, total))
    if len(suf) > suffix_bucket:
        return None
    while len(suf) < suffix_bucket and pre:
        token = pre.pop(0)
        suf.insert(0, token)
    return tuple(pre + suf)


def guard_ok(artifact, request):
    return all(request.get(k) == v for k, v in artifact['guards'].items())


def break_even_hits(compile_us, saving_us):
    return Fraction(compile_us, saving_us)


def break_even_offered(compile_us, saving_us, hit_fraction):
    return break_even_hits(compile_us, saving_us) / hit_fraction


def main():
    cases = 0
    for total in range(0, 9):
        for prefix in range(0, total + 1):
            for bucket in range(0, 9):
                f = migrate_formula(total, prefix, bucket)
                t = migrate_tokens(total, prefix, bucket)
                if (f is None) != (t is None):
                    raise AssertionError('feasibility mismatch')
                if f is None:
                    continue
                cases += 1
                got = (f['prefix_eff'], f['moved'], f['suffix_eff'], f['pad'])
                if got != t[:4]:
                    raise AssertionError('migration formula/token oracle mismatch')
                if t[0] + t[2] != total:
                    raise AssertionError('length split mismatch')

    detected_no_move = False
    detected_front = False
    detected_overfill = False
    for total in range(1, 9):
        for prefix in range(0, total + 1):
            for bucket in range(1, 9):
                f = migrate_formula(total, prefix, bucket)
                if f is not None and f['moved'] > 0:
                    b = bad_no_move(total, prefix, bucket)
                    if b[0] != f['prefix_eff']:
                        detected_no_move = True
                front = bad_front_move(total, prefix, bucket)
                if front is not None and front != tuple(range(total)):
                    detected_front = True
                over = bad_overfill(total, prefix, bucket)
                if over:
                    detected_overfill = True

    req1 = {'op': 'mm', 'shape': (8, 128), 'stride': (128, 1), 'dtype': 'f16', 'const': 4}
    artifact = {
        'name': 'v1',
        'guards': {
            'op': 'mm',
            'shape': (8, 128),
            'stride': (128, 1),
            'dtype': 'f16',
            'const': 4,
        },
    }
    full_index = {('mm', (8, 128), (128, 1), 'f16', 4): artifact}
    buggy_index = {('mm', (8, 128), 'f16'): artifact}
    req_stride = {'op': 'mm', 'shape': (8, 128), 'stride': (256, 1), 'dtype': 'f16', 'const': 4}
    req_const = {'op': 'mm', 'shape': (8, 128), 'stride': (128, 1), 'dtype': 'f16', 'const': 5}

    correct_lookup = full_index.get(('mm', (8, 128), (256, 1), 'f16', 4))
    buggy_stride = buggy_index.get(('mm', (8, 128), 'f16'))
    buggy_const = buggy_index.get(('mm', (8, 128), 'f16'))
    detected_stride = correct_lookup is None and buggy_stride is artifact and not guard_ok(artifact, req_stride)
    detected_const = correct_lookup is None and buggy_const is artifact and not guard_ok(artifact, req_const)

    n = 512
    b = 1024
    att_waste = b * b - n * n
    bad_att_waste = (b - n) * (b - n)
    detected_cost = att_waste != bad_att_waste

    hits = break_even_hits(3_000_000, 50)
    offered = break_even_offered(3_000_000, 50, Fraction(1, 10))
    detected_amort = hits == 60000 and offered == 600000 and hits != offered

    if not detected_no_move:
        raise AssertionError('no-move negative control not detected')
    if not detected_front:
        raise AssertionError('front-move negative control not detected')
    if not detected_overfill:
        raise AssertionError('overfill negative control not detected')
    if not detected_stride:
        raise AssertionError('stride false-reuse negative control not detected')
    if not detected_const:
        raise AssertionError('constant false-reuse negative control not detected')
    if not detected_cost:
        raise AssertionError('quadratic padding negative control not detected')
    if not detected_amort:
        raise AssertionError('hit-rate amortization negative control not detected')

    print('scope=CPU-symbolic-only; no compiler, device, graph-capture, or timing measurement')
    print('prefix_migration_cases=', cases)
    print('negative_controls=', {
        'no_move': detected_no_move,
        'front_move': detected_front,
        'overfill': detected_overfill,
        'guard_stride': detected_stride,
        'guard_const': detected_const,
        'quadratic_padding': detected_cost,
        'hit_rate_amortization': detected_amort,
    })


if __name__ == '__main__':
    main()
